  SELECT DISTINCT ON(raw.sampling_bucket) raw.observed_at,raw.age_seconds,
   raw.views_count AS v,raw.reactions_count AS r,
   raw.views_quality::text AS vq,raw.reactions_quality::text AS rq,raw.interval_uncertain AS uncertain
